create schema auth; create function auth.role() returns text language sql as $$select 'service_role'::text$$; create function auth.uid() returns uuid language sql as $$select null::uuid$$; create function wk_is_agent_or_admin() returns boolean language sql as $$select true$$; create function wk_is_admin() returns boolean language sql as $$select true$$;
create table wk_contacts ("id" uuid default gen_random_uuid() not null, "name" text not null, "phone" text not null, "email" text, "owner_agent_id" uuid, "pipeline_column_id" uuid, "deal_value_pence" integer, "is_hot" boolean default false not null, "custom_fields" jsonb default '{}'::jsonb not null, "last_contact_at" timestamp with time zone, "created_at" timestamp with time zone default now() not null, "updated_at" timestamp with time zone default now() not null, "ai_enabled" boolean default true not null, "ai_reply_count" integer default 0 not null, "ai_reply_last_at" timestamp with time zone, "business_id" uuid, "do_not_call" boolean default false not null, "do_not_call_at" timestamp with time zone, "do_not_call_reason" text, "do_not_call_source" text, "stage_moved_at" timestamp with time zone, "stage_moved_by" uuid, "stage_moved_from" uuid, "stage_move_source" text, "desk" text default 'houses'::text not null, "hostunico_country" text, "hostunico_sms_phone" text, primary key (id));
create table wk_dialer_queue ("id" uuid default gen_random_uuid() not null, "campaign_id" uuid not null, "contact_id" uuid not null, "agent_id" uuid, "status" text default 'pending'::text not null, "priority" integer default 0 not null, "attempts" integer default 0 not null, "scheduled_for" timestamp with time zone, "last_attempt_at" timestamp with time zone, "created_at" timestamp with time zone default now() not null, "hostunico_uplift_hold" boolean default false not null, primary key (id));
create table wk_pipeline_columns ("id" uuid default gen_random_uuid() not null, "pipeline_id" uuid not null, "name" text not null, "colour" text default '#1E9A80'::text not null, "icon" text, "position" integer not null, "sort_order" integer default 0 not null, "is_default_on_timeout" boolean default false not null, "requires_followup" boolean default false not null, "is_terminal" boolean default false not null, "call_script_id" uuid, "coach_style_prompt" text, "coach_script_prompt" text, "coach_profile_id" uuid, "created_at" timestamp with time zone default now() not null, "archived" boolean default false not null, "dialer_closed" boolean default false not null, primary key (id));
create table wk_activities ("id" uuid default gen_random_uuid() not null, "contact_id" uuid, "agent_id" uuid, "call_id" uuid, "kind" text not null, "title" text not null, "body" text, "meta" jsonb, "ts" timestamp with time zone default now() not null, primary key (id));
create table wk_calls ("id" uuid default gen_random_uuid() not null, "twilio_call_sid" text, "twilio_parent_call_sid" text, "contact_id" uuid, "agent_id" uuid, "campaign_id" uuid, "number_id" uuid, "direction" text not null, "status" text default 'queued'::text not null, "answered_by" text, "started_at" timestamp with time zone, "answered_at" timestamp with time zone, "ended_at" timestamp with time zone, "duration_sec" integer, "disposition_column_id" uuid, "agent_note" text, "ai_coach_enabled" boolean default false not null, "from_e164" text, "to_e164" text, "ai_status" text, "current_stage" text, "conference_friendly_name" text, "contact_twilio_call_sid" text, "agent_twilio_call_sid" text, "created_at" timestamp with time zone default now() not null, "voicemail_dropped" boolean default false not null, "voicemail_dropped_at" timestamp with time zone, "script_key" text, "desk" text default 'houses'::text not null, "training_material" boolean default false not null, "training_note" text, "training_marked_at" timestamp with time zone, "training_marked_by" uuid, primary key (id));
create table wk_contact_followups ("id" uuid default gen_random_uuid() not null, "contact_id" uuid not null, "agent_id" uuid not null, "column_id" uuid, "call_id" uuid, "due_at" timestamp with time zone not null, "note" text, "status" text default 'pending'::text not null, "created_at" timestamp with time zone default now() not null, "updated_at" timestamp with time zone default now() not null, primary key (id));
create table sa_listings ("id" uuid default gen_random_uuid() not null, "rightmove_id" text not null, "branch_id" text, "agency" text not null, "agency_phone" text not null, "city" text, "outcode" text, "address" text, "rent_pcm" numeric, "bedrooms" integer, "bathrooms" integer, "property_type" text, "summary" text, "listing_url" text, "photo_urls" text[] default '{}'::text[] not null, "first_listed_at" timestamp with time zone, "let_available_date" text, "wk_contact_id" uuid, "dealt_at" timestamp with time zone default now() not null, "outcome" text, "outcome_note" text, "outcome_at" timestamp with time zone, "outcome_by" uuid, "created_at" timestamp with time zone default now() not null, "source" text default 'rightmove'::text not null, "source_price" text, "report_property" jsonb, "hostunico_call_eligible" boolean default false not null, "hostunico_eligibility_note" text, "hostunico_uplift_status" text default 'pending'::text not null, primary key (id));
create unique index wk_contacts_phone_uniq on wk_contacts(phone);create unique index wk_contacts_email_uniq on wk_contacts(email);
alter table wk_dialer_queue add foreign key (contact_id) references wk_contacts(id);
alter table wk_calls add foreign key (contact_id) references wk_contacts(id);
alter table wk_activities add foreign key (contact_id) references wk_contacts(id);
alter table wk_contact_followups add foreign key (contact_id) references wk_contacts(id);
alter table sa_listings add foreign key (wk_contact_id) references wk_contacts(id);
